const fs = require('fs');

class Fibonacci {
    constructor(mod) {
        this.mod = mod;
        this.calculatedNumbers = new Map();
        this.calculatedNumbers.set(0n, 1n);
        this.calculatedNumbers.set(1n, 1n);
    }

    fib(n) {
        if (this.calculatedNumbers.has(n)) return this.calculatedNumbers.get(n);

        const k = n / 2n;
        let res;
        if (n % 2n === 0n) {
            const fk = this.fib(k);
            const fk1 = this.fib(k - 1n);
            res = (fk * fk + fk1 * fk1) % this.mod;
        } else {
            const fk = this.fib(k);
            const fk1 = this.fib(k + 1n);
            const fkm1 = this.fib(k - 1n);
            res = (fk * fk1 + fkm1 * fk) % this.mod;
        }
        this.calculatedNumbers.set(n, res);
        return res;
    }
}

class Exponentiation {
    static calc(a, b, m) {
        if (b === 0n) return 1n;
        if (b === 1n) return a % m;
        if (b % 2n === 0n) {
            return Exponentiation.calc((a * a) % m, b / 2n, m);
        } else {
            return (a * Exponentiation.calc((a * a) % m, (b - 1n) / 2n, m)) % m;
        }
    }
}

class Solver {
    constructor() {
        this.n = 0n;
        this.k = 0n;
        this.l = 0n;
        this.MOD = 0n;
    }

    read(tokens, index) {
        this.n = BigInt(tokens[index[0]++]);
        this.k = BigInt(tokens[index[0]++]);
        this.l = BigInt(tokens[index[0]++]);
        this.MOD = BigInt(tokens[index[0]++]);
    }

    solve(tokens, index, output) {
        this.read(tokens, index);

        if (this.l !== 64n && ((1n << this.l) - 1n) < this.k) {
            output.push('0');
            return;
        }

        const zeroPos = new Fibonacci(this.MOD).fib(this.n + 1n);
        let onePos = (Exponentiation.calc(2n, this.n, this.MOD) - zeroPos) % this.MOD;
        if (onePos < 0n) onePos += this.MOD;

        let res = 1n;
        for (let i = 0n; i < this.l; i++) {
            if ((this.k & (1n << i)) !== 0n) {
                res = (res * onePos) % this.MOD;
            } else {
                res = (res * zeroPos) % this.MOD;
            }
        }
        output.push(res.toString());
    }
}

function main() {
    const input = fs.readFileSync(0, 'utf-8').trim().split(/\s+/);
    const index = [0];
    const output = [];
    new Solver().solve(input, index, output);
    console.log(output.join('\n'));
}

main();

